=== FILE: rr_arbiter.v ===
`default_nettype none

// rr_arbiter: round-robin arbiter for N requesters.
// Interface:         interface_spec.md (ports, behaviour, reset).
// Microarchitecture: microarchitecture.md (pointer state, wrapping search).
//
// * ptr is the index of the requester with the highest priority this cycle.
// * The winner is the first requester with req high at or after ptr,
//   searching upwards and wrapping from N-1 to 0 (explicit compare, so an N
//   that is not a power of two works).
// * grant is combinational from req and ptr, and is not gated by reset.
// * On a rising edge with a grant, ptr moves to one past the winner; with no
//   request it holds. rst_n is synchronous, active low, and sets ptr to 0.
module rr_arbiter #(
    parameter integer N = 4
) (
    input  wire         clk,
    input  wire         rst_n,
    input  wire [N-1:0] req,
    output wire [N-1:0] grant
);

    localparam integer W    = (N > 1) ? $clog2(N) : 1;
    localparam integer NM1  = N - 1;
    localparam integer ONEI = 1;
    localparam [W-1:0] LAST   = NM1[W-1:0];
    localparam [W-1:0] W_ZERO = {W{1'b0}};
    localparam [W-1:0] W_ONE  = ONEI[W-1:0];
    localparam [N-1:0] G_ONE  = {{(N-1){1'b0}}, 1'b1};

    reg  [W-1:0] ptr;
    reg  [W-1:0] ptr_next;
    reg  [W-1:0] winner;
    reg          found;
    reg  [W-1:0] idx;
    integer      k;

    // Wrapping priority search from ptr. Every variable gets a default first.
    always @(*) begin
        found  = 1'b0;
        winner = W_ZERO;
        idx    = ptr;
        for (k = 0; k < N; k = k + 1) begin
            if (!found && req[idx]) begin
                found  = 1'b1;
                winner = idx;
            end
            if (idx == LAST) begin
                idx = W_ZERO;
            end else begin
                idx = idx + W_ONE;
            end
        end
    end

    assign grant = found ? (G_ONE << winner) : {N{1'b0}};

    // Pointer update: one past the winner, wrapping at N-1; hold with no grant.
    always @(*) begin
        if (!found) begin
            ptr_next = ptr;
        end else if (winner == LAST) begin
            ptr_next = W_ZERO;
        end else begin
            ptr_next = winner + W_ONE;
        end
    end

    always @(posedge clk) begin
        if (!rst_n) begin
            ptr <= W_ZERO;
        end else begin
            ptr <= ptr_next;
        end
    end

`ifdef FORMAL
    // Design-intent properties (microarchitecture.md section 5).
    reg f_past_valid;
    initial f_past_valid = 1'b0;
    always @(posedge clk) f_past_valid <= 1'b1;

    // Reset is active on the first cycle.
    always @(*) begin
        if (!f_past_valid) assume (!rst_n);
    end

    // Distance from ptr to the winner, upwards with wrap.
    wire [W:0] f_dist_w = (winner >= ptr) ? (winner - ptr) : (winner + N - ptr);

    always @(*) begin
        if (f_past_valid) begin
            assert (ptr <= LAST);
            assert (winner <= LAST);
            assert (found == (req != {N{1'b0}}));
            assert ((grant & ~req) == {N{1'b0}});
            assert ((grant & (grant - G_ONE)) == {N{1'b0}});
            if (found) begin
                assert (grant == (G_ONE << winner));
            end else begin
                assert (grant == {N{1'b0}});
            end
        end
    end

    // Pointer: 0 after reset, one past the winner after a grant, else hold.
    always @(posedge clk) begin
        if (f_past_valid) begin
            if (!$past(rst_n)) begin
                assert (ptr == W_ZERO);
            end else if ($past(found)) begin
                if ($past(winner) == LAST) begin
                    assert (ptr == W_ZERO);
                end else begin
                    assert (ptr == $past(winner) + W_ONE);
                end
            end else begin
                assert (ptr == $past(ptr));
            end
        end
    end

    genvar fi;
    generate
        for (fi = 0; fi < N; fi = fi + 1) begin : g_formal
            // Distance from ptr up to requester fi, with wrap.
            wire [W:0] f_dist = (fi >= ptr) ? (fi - ptr) : (fi + N - ptr);
            // Cycles requester fi has waited with req held and no grant.
            reg  [W:0] f_wait;
            always @(posedge clk) begin
                if (!rst_n) begin
                    f_wait <= {(W+1){1'b0}};
                end else if (req[fi] && !grant[fi]) begin
                    f_wait <= f_wait + 1'b1;
                end else begin
                    f_wait <= {(W+1){1'b0}};
                end
            end
            always @(*) begin
                if (f_past_valid) begin
                    // Round-robin order: nobody between ptr and the winner asks.
                    if (found && (f_dist < f_dist_w)) assert (!req[fi]);
                    // Fairness bound with its induction invariant.
                    assert (f_wait + f_dist <= N - 1);
                end
            end
            always @(*) cover (f_past_valid && rst_n && grant[fi]);
            always @(*) cover (f_past_valid && (f_wait == N - 1));
        end
    endgenerate

    always @(*) cover (f_past_valid && rst_n && (req == {N{1'b1}}));
    always @(*) cover (f_past_valid && rst_n && found && (winner == LAST));
`endif

endmodule

`default_nettype wire
=== END FILE ===
=== FILE: rr_arbiter_tb.v ===
// Self-checking testbench for rr_arbiter (interface_spec.md section 6).
// Runs N=4 and N=5 side by side on shared stimulus. Each unit checks grant on
// every rising edge against a reference pointer model, checks the N-1 wait
// bound per requester, and keeps coverage flags that fail the run when a
// required case is not reached.

module rr_arbiter_tb_unit #(
    parameter integer N = 4
) (
    input  wire         clk,
    input  wire         rst_n,
    input  wire [N-1:0] req,
    output wire [31:0]  passed,
    output wire [31:0]  failed,
    output wire         cov_ok
);

    localparam [N-1:0] ZERO = {N{1'b0}};
    localparam [N-1:0] ALL  = {N{1'b1}};
    localparam [N-1:0] ONE  = {{(N-1){1'b0}}, 1'b1};

    wire [N-1:0] grant;

    rr_arbiter #(.N(N)) dut (
        .clk   (clk),
        .rst_n (rst_n),
        .req   (req),
        .grant (grant)
    );

    integer passed_q   = 0;
    integer failed_q   = 0;
    integer ref_ptr    = 0;
    integer all_cycles = 0;
    integer pick;
    integer i;
    integer wait_cnt [0:N-1];

    reg         armed       = 1'b0;
    reg         ran         = 1'b0;
    reg         prev_rst    = 1'b0;
    reg [N-1:0] prev_req    = {N{1'b0}};
    reg [N-1:0] exp_grant;
    reg [N-1:0] bit_i;
    reg         cov_none    = 1'b0;
    reg         cov_held    = 1'b0;
    reg         cov_maxwait = 1'b0;
    reg         cov_rst     = 1'b0;
    reg [N-1:0] cov_alone   = {N{1'b0}};

    assign passed = passed_q;
    assign failed = failed_q;
    assign cov_ok = cov_none && (cov_alone == ALL) && (all_cycles >= 2 * N) &&
                    cov_held && cov_maxwait && cov_rst;

    // Reference model: first requester at or after p, wrapping at N; -1 if none.
    function integer rr_pick;
        input [N-1:0] r;
        input integer p;
        integer s, j;
        begin
            rr_pick = -1;
            for (s = N - 1; s >= 0; s = s - 1) begin
                j = (p + s) % N;
                if (((r >> j) & ONE) != ZERO) rr_pick = j;
            end
        end
    endfunction

    always @(posedge clk) begin
        if (armed) begin
            // Grant against the reference pointer model.
            pick = rr_pick(req, ref_ptr);
            exp_grant = (pick >= 0) ? (ONE << pick) : ZERO;
            if (grant !== exp_grant) begin
                $error("rr_arbiter_tb N=%0d: grant %b, expected %b (req %b, ptr %0d, rst_n %b)",
                       N, grant, exp_grant, req, ref_ptr, rst_n);
                failed_q = failed_q + 1;
            end else begin
                passed_q = passed_q + 1;
            end
            // One-hot or zero, and only to a requester.
            if (((grant & ~req) != ZERO) || ((grant & (grant - ONE)) != ZERO)) begin
                $error("rr_arbiter_tb N=%0d: grant %b is not one-hot-or-zero within req %b",
                       N, grant, req);
                failed_q = failed_q + 1;
            end else begin
                passed_q = passed_q + 1;
            end
            // Fairness: a held request waits at most N-1 cycles.
            for (i = 0; i < N; i = i + 1) begin
                bit_i = ONE << i;
                if (rst_n && ((req & bit_i) != ZERO) && ((grant & bit_i) == ZERO)) begin
                    wait_cnt[i] = wait_cnt[i] + 1;
                    if (wait_cnt[i] > N - 1) begin
                        $error("rr_arbiter_tb N=%0d: requester %0d has waited %0d cycles",
                               N, i, wait_cnt[i]);
                        failed_q = failed_q + 1;
                    end
                    if (wait_cnt[i] == N - 1) cov_maxwait = 1'b1;
                end else begin
                    if (rst_n && ((req & bit_i) != ZERO) && (wait_cnt[i] > 0)) begin
                        passed_q = passed_q + 1;
                    end
                    wait_cnt[i] = 0;
                end
                if (rst_n && (req == bit_i)) cov_alone = cov_alone | bit_i;
                if (rst_n && prev_rst && ((req & prev_req & bit_i) != ZERO) &&
                    (((req ^ prev_req) & ~bit_i) != ZERO)) cov_held = 1'b1;
            end
            // Coverage.
            if (rst_n && (req == ZERO)) cov_none = 1'b1;
            if (rst_n && (req == ALL)) all_cycles = all_cycles + 1;
            if (!rst_n && ran && (req != ZERO)) cov_rst = 1'b1;
            if (rst_n) ran = 1'b1;
            // Model update.
            if (!rst_n) begin
                ref_ptr = 0;
            end else if (pick >= 0) begin
                ref_ptr = (pick + 1) % N;
            end
        end
        if (!rst_n) begin
            armed   = 1'b1;
            ref_ptr = 0;
            for (i = 0; i < N; i = i + 1) wait_cnt[i] = 0;
        end
        prev_req = req;
        prev_rst = rst_n;
    end

endmodule

module rr_arbiter_tb;

    reg         clk = 1'b0;
    reg         rst_n;
    reg  [3:0]  req4;
    reg  [4:0]  req5;
    reg  [31:0] lfsr;
    reg  [8*64-1:0] nonce;
    integer     passed;
    integer     failed;
    integer     i;

    wire [31:0] p4, f4, p5, f5;
    wire        c4, c5;

    always #5 clk = ~clk;

    rr_arbiter_tb_unit #(.N(4)) u4 (
        .clk (clk), .rst_n (rst_n), .req (req4),
        .passed (p4), .failed (f4), .cov_ok (c4)
    );

    rr_arbiter_tb_unit #(.N(5)) u5 (
        .clk (clk), .rst_n (rst_n), .req (req5),
        .passed (p5), .failed (f5), .cov_ok (c5)
    );

    function [31:0] xs32;
        input [31:0] s;
        reg   [31:0] t;
        begin
            t    = s ^ (s << 13);
            t    = t ^ (t >> 17);
            xs32 = t ^ (t << 5);
        end
    endfunction

    initial begin
        rst_n  = 1'b0;
        req4   = 4'b0000;
        req5   = 5'b00000;
        lfsr   = 32'h1234_5678;
        nonce  = {(8*64){1'b0}};
        passed = 0;
        failed = 0;

        // Reset with no traffic.
        repeat (3) @(negedge clk);

        // Everyone requesting from reset: strict rotation 0, 1, ..., N-1.
        rst_n = 1'b1;
        req4  = 4'b1111;
        req5  = 5'b11111;
        repeat (20) @(negedge clk);

        // No requests.
        req4 = 4'b0000;
        req5 = 5'b00000;
        repeat (3) @(negedge clk);

        // Each requester alone.
        for (i = 0; i < 5; i = i + 1) begin
            req4 = (i < 4) ? (4'b0001 << i) : 4'b0000;
            req5 = 5'b00001 << i;
            repeat (2) @(negedge clk);
        end

        // A held request (requester 2) among changing others.
        for (i = 0; i < 40; i = i + 1) begin
            lfsr = xs32(lfsr);
            req4 = lfsr[3:0] | 4'b0100;
            req5 = lfsr[8:4] | 5'b00100;
            @(negedge clk);
        end

        // Random subsets, dense: requests dropped and raised again.
        for (i = 0; i < 200; i = i + 1) begin
            lfsr = xs32(lfsr);
            req4 = lfsr[3:0];
            req5 = lfsr[8:4];
            @(negedge clk);
        end

        // Random subsets, sparse.
        for (i = 0; i < 200; i = i + 1) begin
            lfsr = xs32(lfsr);
            req4 = lfsr[3:0] & lfsr[19:16];
            req5 = lfsr[8:4] & lfsr[28:24];
            @(negedge clk);
        end

        // Reset during traffic.
        for (i = 0; i < 4; i = i + 1) begin
            rst_n = 1'b0;
            lfsr  = xs32(lfsr);
            req4  = lfsr[3:0] | 4'b1000;
            req5  = lfsr[8:4] | 5'b10000;
            @(negedge clk);
        end
        rst_n = 1'b1;
        req4  = 4'b1111;
        req5  = 5'b11111;
        repeat (12) @(negedge clk);
        for (i = 0; i < 100; i = i + 1) begin
            lfsr = xs32(lfsr);
            req4 = lfsr[3:0];
            req5 = lfsr[8:4];
            @(negedge clk);
        end

        // Quiet end.
        req4 = 4'b0000;
        req5 = 5'b00000;
        repeat (2) @(negedge clk);

        passed = p4 + p5;
        failed = f4 + f5;
        if (!c4) begin
            $error("rr_arbiter_tb: a coverage goal was not reached at N=4");
            failed = failed + 1;
        end
        if (!c5) begin
            $error("rr_arbiter_tb: a coverage goal was not reached at N=5");
            failed = failed + 1;
        end

        if ($value$plusargs("nirmaan_nonce=%s", nonce) == 0) begin
            $display("rr_arbiter_tb: no nirmaan_nonce plusarg given");
        end
        $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, passed, failed);
        $finish;
    end

endmodule
